  "implementation": "def solve(case):
    word_token_indices = case['word_token_indices']
    word_labels = case['word_labels']
    token_count = case['token_count']

    if len(word_token_indices) != len(word_labels):
        raise ValueError('Mismatch between number of word groups and word labels')

    # Flatten all token indices to check coverage and overlap
    all_indices = []
    for group in word_token_indices:
        for idx in group:
            if not isinstance(idx, int) or idx < 0 or idx >= token_count:
                raise ValueError(f'Invalid token index {idx}')
            all_indices.append(idx)

    if len(all_indices) != token_count:
        raise ValueError('Total token indices do not match token_count')
    if len(set(all_indices)) != token_count:
        raise ValueError('Duplicate token indices found (overlap)')

    # Build token_labels
    token_labels = [0] * token_count  # placeholder, will assign
    for group_idx, indices in enumerate(word_token_indices):
        label = word_labels[group_idx]
        for idx in indices:
            token_labels[idx] = label

    # Verify coverage (should be guaranteed by previous checks but safe)
    if any(t is None for t in token_labels):  # but we used 0 as placeholder; better initialize with -1
        # Actually we used 0 as placeholder; we need to detect uncovered tokens differently
        # Let's initialize with a sentinel like None or -1
        raise ValueError('Internal error: placeholder used')

    # Better approach: use sentinel value -1
    sentinel = -1
    token_labels = [sentinel] * token_count
    for group_idx, indices in enumerate(word_token_indices):
        label = word_labels[group_idx]
        for idx in indices:
            token_labels[idx] = label
    if any(t == sentinel for t in token_labels):
        raise ValueError('Some tokens are not covered by any word group')

    kept_indices = [i for i, lb in enumerate(token_labels) if lb == 1]

    return {
        'kept_indices': kept_indices,
        'token_labels': token_labels
    }"
